#!name=当当阅读
#!desc=fmz200/wool_scripts · 某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思

[MITM]
hostname = e.dangdang.com, api.dangdang.com, mapi.dangdang.com

[Rewrite]
request if ${url} ~= /^https?:\/\/e\.dangdang\.com\/media\/api.+\?action=getDeviceStartPage/i then reject(404)
request if ${url} ~= /^https?:\/\/e\.dangdang\.com\/.+?getDeviceStartPage/i then reject(404)
request if ${url} ~= /^https?:\/\/api\.dangdang\.com\/mapi\d\/mobile\/init/i then reject(404)
request if ${url} ~= /^https?:\/\/mapi\.dangdang\.com\/index\.php\?action=init/i then reject(404)
